import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Summary-Functions-for-Groups-of-Cells.md","filePath":"manual-en/CTABLES-Summary-Functions-for-Groups-of-Cells.md","lastUpdated":1785684581000}'),r={name:"manual-en/CTABLES-Summary-Functions-for-Groups-of-Cells.md"};function s(n,t,l,i,c,u){return e(),a("div",null,[...t[0]||(t[0]=[o('<h4 id="_15-7-2-2-summary-functions-for-groups-of-cells" tabindex="-1">15.7.2.2 Summary Functions for Groups of Cells <a class="header-anchor" href="#_15-7-2-2-summary-functions-for-groups-of-cells" aria-label="Permalink to &quot;15.7.2.2 Summary Functions for Groups of Cells&quot;">​</a></h4><p>These summary functions summarize over multiple cells within an area of the output chosen by the user and specified as part of the function name. The following basic areas are supported, in decreasing order of size:</p><p><code>TABLE</code></p><p>A <em>section</em>. Stacked variables divide sections of the output from each other. sections may span multiple layers.</p><p><code>LAYER</code></p><p>A section within a single layer.</p><p><code>SUBTABLE</code></p><p>A <em>subtable</em> , whose contents are the cells that pair an innermost row variable and an innermost column variable within a single layer.</p><p>The following shows how the output for the table expression <code>hasBeenPassengerOfDesignatedDriver &gt; hasBeenPassengerOfDrunkDriver BY isLicensedDriver &gt; hasHostedEventWithAlcohol + hasBeenDesignatedDriver BY gender</code>8 is divided up into <code>TABLE</code>, <code>LAYER</code>, and <code>SUBTABLE</code> areas. Each unique value for Table ID is one section, and similarly for Layer ID and Subtable ID. Thus, this output has two <code>TABLE</code> areas (one for <code>isLicensedDriver</code> and one for <code>hasBeenDesignatedDriver</code>), four <code>LAYER</code> areas (for those two variables, per layer), and 12 <code>SUBTABLE</code> areas.</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th></th><th>Yes</th><th>No</th><th>Yes</th><th>No</th><th></th><th></th></tr></thead><tbody><tr><td>Male</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>licensed</td><td>desDrv</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>hostAlc</td><td>hostAlc</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Yes</td><td>No</td><td>Yes</td><td>No</td><td></td><td></td></tr><tr><td>desPas</td><td>Yes</td><td>druPas</td><td>Yes</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>1</td><td>1</td><td>2</td><td>2</td><td>3</td><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>No</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>1</td><td>1</td><td>2</td><td>2</td><td>3</td><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>No</td><td>druPas</td><td>Yes</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>4</td><td>4</td><td>5</td><td>5</td><td>6</td><td>6</td><td></td><td></td><td></td><td></td></tr><tr><td>No</td><td>Table ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td></tr><tr><td>Layer ID</td><td>1</td><td>1</td><td>1</td><td>1</td><td>2</td><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>Subtable ID</td><td>4</td><td>4</td><td>5</td><td>5</td><td>6</td><td>6</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><code>CTABLES</code> also supports the following areas that further divide a subtable or a layer within a section:</p><p><code>LAYERROW</code><code>LAYERCOL</code></p><p>A row or column, respectively, in one layer of a section.</p><p><code>ROW</code><code>COL</code></p><p>A row or column, respectively, in a subtable.</p><p>The following summary functions for groups of cells are available for each area described above, for both categorical and scale variables:</p><p><code>_area_ PCT</code> or <code>_area_ PCT.COUNT</code> (“ <em>Area</em> %”, PCT40.1)</p><p>A percentage of total counts within area.</p><p><code>_area_ PCT.VALIDN</code> (“ <em>Area</em> Valid N %”, PCT40.1)</p><p>A percentage of total counts for valid values within area.</p><p><code>_area_ PCT.TOTALN</code> (“ <em>Area</em> Total N %”, PCT40.1)</p><p>A percentage of total counts for all values within area.</p><p>Scale variables and totals and subtotals for categorical variables may use the following additional group cell summary function:</p><p><code>_area_ PCT.SUM</code> (“ <em>Area</em> Sum %”, PCT40.1)</p><p>Percentage of the sum of the values within area.</p><h4 id="footnotes" tabindex="-1">Footnotes <a class="header-anchor" href="#footnotes" aria-label="Permalink to &quot;Footnotes&quot;">​</a></h4><h5 id="_8" tabindex="-1">(8) <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;(8)&quot;">​</a></h5><p>This is not necessarily a meaningful table. To make it easier to read, short variable labels are used.</p>',28)])])}const f=d(r,[["render",s]]);export{h as __pageData,f as default};
